    <style>
      :root{--doc-teal:#065f46;--doc-teal2:#0d9488;--doc-teal3:#14b8a6;--doc-gold:#d97706;--doc-bg:#f0fdfa;--doc-ink:#0f172a;--doc-muted:#64748b}
      .doc-hero{background:linear-gradient(135deg,#065f46 0%,#0d9488 50%,#14b8a6 100%);color:#fff;padding:90px 20px 70px;text-align:center;position:relative;overflow:hidden}
      .doc-hero::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 20% 30%,rgba(217,119,6,0.15) 0%,transparent 50%);pointer-events:none}
      .doc-hero .eyebrow{display:inline-flex;align-items:center;gap:8px;background:rgba(217,119,6,0.2);color:#fed7aa;padding:8px 18px;border-radius:99px;font-size:13px;font-weight:700;letter-spacing:0.6px;text-transform:uppercase;margin-bottom:20px;border:1px solid rgba(217,119,6,0.3)}
      .doc-hero h1{color:#fff;font-size:44px;line-height:1.18;margin:0 auto 18px;max-width:1000px;font-weight:800;position:relative}
      .doc-hero h1 .accent{color:#fbbf24}
      .doc-hero p.lede{color:#d1fae5;font-size:19px;line-height:1.65;max-width:840px;margin:0 auto 30px;font-weight:400;position:relative}
      .doc-hero .cities-strip{max-width:900px;margin:0 auto 26px;padding:14px 22px;background:rgba(255,255,255,0.08);border-radius:12px;font-size:14px;color:#e6fffa;position:relative;border:1px solid rgba(255,255,255,0.12)}
      .doc-hero .cities-strip strong{color:#fbbf24;margin-right:8px}
      .doc-hero .cta-row{margin-top:26px;display:flex;justify-content:center;gap:12px;flex-wrap:wrap;position:relative}
      .doc-hero a.cta-primary{background:#fbbf24;color:#0f172a;padding:18px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:17px;display:inline-block;box-shadow:0 8px 24px rgba(251,191,36,0.35)}
      .doc-hero a.cta-primary:hover{background:#f59e0b;color:#0f172a;transform:translateY(-2px)}
      .doc-hero a.cta-wa{background:#25d366;color:#fff;padding:18px 34px;border-radius:10px;text-decoration:none;font-weight:800;font-size:17px;display:inline-block}
      .doc-hero .stats{margin-top:36px;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:18px;max-width:900px;margin-left:auto;margin-right:auto;position:relative}
      .doc-hero .stat{background:rgba(255,255,255,0.09);padding:18px 12px;border-radius:12px;border:1px solid rgba(255,255,255,0.14)}
      .doc-hero .stat .num{font-size:28px;font-weight:800;color:#fbbf24;line-height:1}
      .doc-hero .stat .lbl{font-size:12px;color:#d1fae5;margin-top:4px;letter-spacing:0.3px}

      /* DERMATRIX CASE STUDY BAND — competitor advantage */
      .doc-case{background:#ecfdf5;padding:64px 20px}
      .doc-case-wrap{max-width:1120px;margin:0 auto;display:grid;grid-template-columns:1fr 1.5fr;gap:36px;align-items:center;background:#fff;border-radius:16px;padding:38px 34px;box-shadow:0 8px 32px rgba(6,95,70,0.1);border:1px solid #a7f3d0}
      .doc-case-wrap .badge{display:inline-flex;align-items:center;gap:8px;background:#065f46;color:#fff;padding:6px 14px;border-radius:99px;font-size:11.5px;font-weight:700;letter-spacing:0.6px;text-transform:uppercase;margin-bottom:14px}
      .doc-case-wrap h2{color:#065f46;font-size:30px;margin:0 0 16px;line-height:1.25;font-weight:800}
      .doc-case-wrap p{color:#334155;font-size:16px;line-height:1.75;margin:0 0 14px}
      .doc-case-wrap ul{list-style:none;padding:0;margin:16px 0}
      .doc-case-wrap ul li{padding:8px 0 8px 26px;position:relative;color:#334155;font-size:15px;line-height:1.6}
      .doc-case-wrap ul li::before{content:"✓";position:absolute;left:0;top:8px;color:#0d9488;font-weight:800;font-size:16px}
      .doc-case-wrap .case-metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:22px}
      .doc-case-wrap .case-metrics .m{background:linear-gradient(135deg,#065f46,#0d9488);color:#fff;padding:18px;border-radius:10px;text-align:center}
      .doc-case-wrap .case-metrics .m .n{font-size:22px;font-weight:800;line-height:1}
      .doc-case-wrap .case-metrics .m .l{font-size:11.5px;margin-top:4px;color:#a7f3d0;text-transform:uppercase;letter-spacing:0.4px}

      /* SECTIONS */
      .doc-section{padding:70px 20px;background:#fff}
      .doc-section.alt{background:#f0fdfa}
      .doc-section h2{color:#065f46;font-size:34px;text-align:center;margin:0 auto 12px;max-width:820px;font-weight:800;line-height:1.25}
      .doc-section p.section-lede{color:#475569;font-size:17px;line-height:1.7;text-align:center;max-width:780px;margin:0 auto 44px}
      .doc-container{max-width:1160px;margin:0 auto}
      .doc-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px}
      .doc-card{background:#fff;border-radius:12px;padding:28px;box-shadow:0 2px 10px rgba(13,148,136,0.06);border:1px solid #a7f3d0;transition:transform 0.2s,box-shadow 0.2s}
      .doc-card:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(13,148,136,0.18)}
      .doc-card .ico{font-size:34px;color:#0d9488;margin-bottom:14px;display:block}
      .doc-card h3{color:#065f46;font-size:19px;margin:0 0 10px;font-weight:700;line-height:1.35}
      .doc-card p{color:#475569;font-size:15px;line-height:1.7;margin:0}

      .doc-process{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px;margin-top:36px}
      .doc-process .step{background:#fff;border-radius:12px;padding:24px;text-align:center;border:1px solid #a7f3d0;position:relative}
      .doc-process .step .num{background:linear-gradient(135deg,#065f46,#0d9488);color:#fff;width:44px;height:44px;border-radius:99px;display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:18px;margin-bottom:12px}
      .doc-process .step h4{color:#065f46;font-size:16px;margin:0 0 8px;font-weight:700}
      .doc-process .step p{color:#64748b;font-size:14px;line-height:1.65;margin:0}

      .doc-specs-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:22px}
      .doc-spec{background:#fff;border-left:4px solid #0d9488;padding:18px 20px;border-radius:8px}
      .doc-spec strong{color:#065f46;display:block;font-size:15px;margin-bottom:4px}
      .doc-spec span{color:#64748b;font-size:13.5px;line-height:1.55}

      .doc-cities{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-top:24px}
      .doc-cities .chip{background:#0d9488;color:#fff;padding:10px 18px;border-radius:99px;font-size:14px;font-weight:600;box-shadow:0 2px 6px rgba(13,148,136,0.2)}
      .doc-cities .chip.gold{background:#d97706}

      /* PRICING */
      .doc-pricing{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px;margin-top:20px}
      .doc-tier{background:#fff;border-radius:14px;padding:32px 26px;border:2px solid #a7f3d0;position:relative;transition:transform 0.2s,box-shadow 0.2s}
      .doc-tier.featured{border-color:#d97706;transform:scale(1.03);box-shadow:0 12px 40px rgba(217,119,6,0.18)}
      .doc-tier.featured::before{content:"Most Popular";position:absolute;top:-14px;left:50%;transform:translateX(-50%);background:#d97706;color:#fff;padding:6px 16px;border-radius:99px;font-size:11px;font-weight:700;letter-spacing:0.5px;text-transform:uppercase}
      .doc-tier h3{color:#065f46;font-size:22px;margin:0 0 6px;font-weight:800}
      .doc-tier .ideal{color:#64748b;font-size:13px;margin-bottom:20px;font-weight:500}
      .doc-tier .price{color:#0f172a;font-size:32px;font-weight:800;margin-bottom:4px}
      .doc-tier .price small{font-size:14px;color:#64748b;font-weight:500}
      .doc-tier .price-alt{color:#64748b;font-size:13px;margin-bottom:22px}
      .doc-tier ul{list-style:none;padding:0;margin:0 0 24px;text-align:left}
      .doc-tier ul li{padding:8px 0;color:#334155;font-size:14.5px;line-height:1.55;position:relative;padding-left:24px}
      .doc-tier ul li::before{content:"✓";position:absolute;left:0;top:8px;color:#0d9488;font-weight:800}
      .doc-tier a.btn-select{display:block;background:#0d9488;color:#fff;padding:14px 20px;border-radius:8px;text-decoration:none;font-weight:700;text-align:center;font-size:15px;transition:background 0.2s}
      .doc-tier a.btn-select:hover{background:#065f46;color:#fff}
      .doc-tier.featured a.btn-select{background:linear-gradient(135deg,#d97706,#f59e0b);color:#fff}

      /* PACKAGE FORM */
      .doc-form-wrap{max-width:720px;margin:36px auto 0;background:#fff;border-radius:14px;padding:36px 32px;box-shadow:0 8px 32px rgba(13,148,136,0.1);border:1px solid #a7f3d0}
      .doc-form-wrap h3{color:#065f46;font-size:24px;margin:0 0 8px;text-align:center;font-weight:700}
      .doc-form-wrap p.sub{color:#64748b;font-size:14.5px;text-align:center;margin:0 0 24px}
      .doc-form label{display:block;color:#334155;font-size:13.5px;font-weight:600;margin-bottom:6px}
      .doc-form input,.doc-form select,.doc-form textarea{width:100%;padding:12px 14px;border:1px solid #cbd5e1;border-radius:8px;font-size:15px;margin-bottom:16px;font-family:inherit}
      .doc-form input:focus,.doc-form select:focus,.doc-form textarea:focus{outline:none;border-color:#0d9488;box-shadow:0 0 0 3px rgba(13,148,136,0.12)}
      .doc-form button{width:100%;background:linear-gradient(135deg,#065f46,#0d9488);color:#fff;border:none;padding:16px 22px;border-radius:8px;font-weight:800;font-size:16px;cursor:pointer;letter-spacing:0.3px}
      .doc-form button:hover{background:linear-gradient(135deg,#064e3b,#0f766e)}
      .doc-form .form-note{color:#64748b;font-size:12px;text-align:center;margin-top:12px}
      #doc-form-success{display:none;background:#dcfce7;border-left:4px solid #16a34a;color:#166534;padding:20px 24px;border-radius:10px;margin-top:20px;text-align:center;font-weight:600}
      #doc-form-error{display:none;background:#fef2f2;border-left:4px solid #dc2626;color:#991b1b;padding:20px 24px;border-radius:10px;margin-top:20px}

      /* FAQ */
      .doc-faq{max-width:900px;margin:0 auto}
      .doc-faq-item{border-bottom:1px solid #e2e8f0;padding:22px 0}
      .doc-faq-item h3{color:#065f46;font-size:19px;margin:0 0 10px;line-height:1.4;font-weight:700}
      .doc-faq-item div{color:#334155;font-size:15px;line-height:1.75}
      .doc-faq-item div a{color:#0d9488;font-weight:600;text-decoration:none;border-bottom:1px solid #a7f3d0}

      /* COMPARISON TABLE */
      .doc-compare{background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 4px 20px rgba(13,148,136,0.08);border:1px solid #a7f3d0;margin-top:20px}
      .doc-compare table{width:100%;border-collapse:collapse}
      .doc-compare th,.doc-compare td{padding:16px 20px;text-align:left;border-bottom:1px solid #e2e8f0;font-size:14.5px}
      .doc-compare th{background:#065f46;color:#fff;font-weight:700;letter-spacing:0.2px;font-size:13.5px;text-transform:uppercase}
      .doc-compare td.itd{background:#ecfdf5;color:#065f46;font-weight:600}
      .doc-compare td.competitor{color:#64748b}

